// Real Chromium + shipped SxLock functions. Fixtures are generated by make_fixtures.py.
// DATA_DIR=/absolute/test-data PLAYWRIGHT_MODULE=/path/to/playwright BROWSER_EXECUTABLE=/path/to/chrome node media-regression.cjs
const fs=require('node:fs'),path=require('node:path'),http=require('node:http'),assert=require('node:assert/strict');
const repo=path.resolve(__dirname,'../../../..'),data=path.resolve(process.env.DATA_DIR);
const {chromium}=require(process.env.PLAYWRIGHT_MODULE||'playwright');
async function main(){
 const server=http.createServer(async(q,s)=>{
  const url=new URL(q.url,'http://test');
  if(q.method==='POST'&&url.pathname.startsWith('/results/')){
   const chunks=[];for await(const b of q)chunks.push(b);
   fs.writeFileSync(path.join(data,path.basename(url.pathname)),Buffer.concat(chunks));s.end('saved');return;
  }
  const baseline=url.pathname.startsWith('/baseline/');
  const base=url.pathname.startsWith('/fixtures/')?data:baseline?path.join(data,'baseline'):repo;
  const relative=decodeURIComponent(url.pathname.replace(/^\/(repo|baseline|fixtures)\//,''));
  let file=path.resolve(base,relative);
  if(!file.startsWith(base+path.sep)){s.writeHead(403);s.end();return;}
  if(baseline&&!fs.existsSync(file))file=path.resolve(repo,relative);
  try{const st=fs.statSync(file);let start=0,end=st.size-1;
   if(q.headers.range){const m=q.headers.range.match(/bytes=(\d+)-(\d*)/);start=Number(m[1]);if(m[2])end=Number(m[2]);s.statusCode=206;s.setHeader('Content-Range',`bytes ${start}-${end}/${st.size}`);}
   s.setHeader('Content-Type',/\.m?js$/.test(file)?'text/javascript':file.endsWith('.html')?'text/html':file.endsWith('.json')?'application/json':file.endsWith('.mp4')?'video/mp4':'application/octet-stream');
   s.setHeader('Content-Length',end-start+1);s.setHeader('Accept-Ranges','bytes');fs.createReadStream(file,{start,end}).pipe(s);
  }catch{s.writeHead(404);s.end('not found');}
 }).listen(0,'127.0.0.1');
 await new Promise(r=>server.on('listening',r));
 const args=['--no-sandbox','--autoplay-policy=no-user-gesture-required','--disable-dev-shm-usage'];
 const browser=await chromium.launch({executablePath:process.env.BROWSER_EXECUTABLE||undefined,args,headless:true});
 const base='http://127.0.0.1:'+server.address().port;
 const page=await browser.newPage({viewport:{width:1000,height:1200},acceptDownloads:true});
 page.on('console',m=>{if(m.type()!=='error')console.log(m.text())});
 page.on('pageerror',e=>console.error('PAGE ERROR',e.message));
 try{
  await page.goto(base+'/repo/tools-home/tools/sxlock/index.html');
  await page.waitForFunction(()=>window.SxLock);await page.evaluate(()=>SxLock.ready);
  if(process.env.BASELINE_ONLY!=='1'){
  const results=await page.evaluate(async()=>{
   const engine=await import('./export-engine.mjs');
   const file=await(await fetch('/fixtures/fixture_40s.mp4')).blob();
   const ac=await SxLock.audioContext(),sound=ac.createBuffer(2,4800,48000);
   for(let c=0;c<2;c++)for(let i=0;i<sound.length;i++)sound.getChannelData(c)[i]=Math.sin(i/48000*2*Math.PI*2700)*.025;
   SxLock.sounds.set('regression-fx',{id:'regression-fx',name:'Regression tone',origin:'import',buffer:sound,builtin:true});
   document.getElementById('effectsBus').value=100;
   const cue=(start,duration=.1,loop=false)=>({soundId:'regression-fx',start,duration,loop,offset:0,volume:100,enabled:true});
   const off=new OfflineAudioContext(2,8*48000,48000);
   SxLock.placeSource(off,cue(863/25),sound,off.destination,32,0,40);
   const pcm=(await off.startRendering()).getChannelData(0),firstSample=(863-800)*1920;
   if(pcm.subarray(0,firstSample+1).some(x=>Math.abs(x)>1e-8)
      ||Math.abs(pcm[firstSample+1]-sound.getChannelData(0)[1])>1e-7)throw Error('F863 effect sample placement moved');
   const cases={C:[],D:[cue(2)],E:[cue(2),cue(16),cue(34.52),cue(39.8)],F:[cue(16,1.5,true),cue(16.04,.8,true)],G:[cue(34.48),cue(34.52),cue(34.56)],Moved:[cue(4),cue(34.52)],Deleted:[]};
   const results={};
   async function render(name,source,cues,extra={}){
    console.log('TEST '+name);
    const out=await engine.exportVideo({file:source,hasEffects:cues.length>0,...extra,
     placeEffects:async(off,at,end)=>{for(const c of cues)if(c.enabled)SxLock.placeSource(off,c,sound,off.destination,at,0,end)}});
    await fetch('/results/'+name+'.mp4',{method:'POST',body:out.blob});results[name]=out.report;return out.blob;
   }
   let repeat;
   for(const [name,cues] of Object.entries(cases)){const blob=await render(name,file,cues);if(name==='E')repeat=blob;}
   await render('H',repeat,[]);
   for(const name of ['fixture_44100','fixture_audio_offset','fixture_30fps','color_full709']){
    const source=await(await fetch('/fixtures/'+name+'.mp4')).blob();await render(name+'_out',source,[cue(2)]);
   }
   const shortAudio=await(await fetch('/fixtures/fixture_30fps_short_audio.mp4')).blob();
   await render('fixture_30fps_short_audio_out',shortAudio,[]);
   if(results.fixture_30fps_short_audio_out.audio!=='packet-copy')throw Error('Short original audio was unnecessarily encoded');
   // Cancellation must not offer a partial file or alter the next job.
   let cancel=false;
   try{await engine.exportVideo({file,hasEffects:true,cancelled:()=>cancel,onProgress:()=>{cancel=true}});throw Error('Cancellation was ignored');}
   catch(e){if(!e.message.includes('cancelled'))throw e;results.cancelled=true;}
   await render('AfterCancel',file,[]);
   return results;
  });
  fs.writeFileSync(path.join(data,'regression.json'),JSON.stringify(results,null,2));
  assert.equal(results.C.video,'file-copy');assert.equal(results.H.video,'file-copy');assert.equal(results.E.outputFrames,1000);
  // Exercise the actual UI export handler, file creation and native download.
  await page.locator('#videoFile').setInputFiles(path.join(data,'fixture_40s.mp4'));
  await page.waitForFunction(()=>document.getElementById('video').readyState>=2);
  const start=await page.evaluate(async()=>{const c=await SxLock.insert('regression-fx',{start:.101,volume:20});return c.start});
  assert.equal(start,.12);
  await page.locator('#exportSection').evaluate(el=>el.open=true);
  await page.locator('#exportVideo').click();
  await page.waitForFunction(()=>!document.getElementById('result').hidden,null,{timeout:120000});
  const download=page.waitForEvent('download');await page.locator('#download').click();await(await download).saveAs(path.join(data,'UI.mp4'));
  console.log('PASS: engine matrix, cancellation, frame placement and UI export/download');
  }
  if(process.env.TEST_BASELINE==='1'){
   await page.goto(base+'/baseline/tools-home/tools/sxlock/index.html');
   await page.waitForFunction(()=>window.SxLock);await page.evaluate(()=>SxLock.ready);
   await page.locator('#videoFile').setInputFiles(path.join(data,'color_full709.mp4'));
   await page.waitForFunction(()=>document.getElementById('video').readyState>=2);
   await page.locator('#exportSection').evaluate(el=>el.open=true);
   await page.locator('#format').selectOption('video/mp4',{force:true});await page.locator('#exportVideo').click();
   await page.waitForFunction(()=>!document.getElementById('result').hidden,null,{timeout:30000});
   const d=page.waitForEvent('download');await page.locator('#download').click();await(await d).saveAs(path.join(data,'old_sxlock_color.mp4'));
   // Isolate the old H.264 video encoder even on Linux without native AAC encoding.
   await page.evaluate(()=>{const type='video/mp4;codecs=avc1.42001f,opus';document.getElementById('format').add(new Option('H.264 diagnostic',type));document.getElementById('format').value=type;document.getElementById('result').hidden=true;});
   await page.locator('#exportVideo').click();await page.waitForFunction(()=>!document.getElementById('result').hidden,null,{timeout:30000});
   const h=page.waitForEvent('download');await page.locator('#download').click();await(await h).saveAs(path.join(data,'old_sxlock_h264_color.mp4'));
   await page.goto(base+'/repo/tools-home/tools/aspectlock/index.html');
   await page.evaluate(async()=>{startFrame=9999;const file=await(await fetch('/fixtures/color_full709.mp4')).blob();bv.src=URL.createObjectURL(file);ov.src=URL.createObjectURL(file);await Promise.all([bv,ov].map(v=>new Promise(r=>v.onloadeddata=r)));});
   await page.locator('#render').click();await page.waitForFunction(()=>typeof renderedBlob!=='undefined'&&renderedBlob?.size>0,null,{timeout:30000});
   await page.evaluate(async()=>{await fetch('/results/aspectlock_color.webm',{method:'POST',body:renderedBlob});});
   console.log('PASS: actual baseline SxLock and unchanged AspectLock controlled captures');
  }
 }finally{await browser.close();server.close();}
}
main().catch(e=>{console.error(e);process.exit(1)});
